const orderMachine = setup({
  actors: { reserveStock: fromPromise(({ input }) => api.reserve(input.cid)) },
  guards:   { paid: ({ context }) => context.payment === 'ok' },
}).createMachine({
  initial: 'awaitingPayment',
  states: {
    awaitingPayment: {
      after: { 3600000: 'compensating' },                 // deadline
      on: { PAYMENT_OK: { guard: 'paid', target: 'awaitingStock' } },
    },
    awaitingStock: { invoke: { src: 'reserveStock', onDone: 'done', onError: 'compensating' } },
    done: { type: 'final' },
    compensating: { entry: ({ context }) => api.releaseCredit(context.cid) },
  },
});

const actor = createActor(orderMachine, { snapshot: await store.load(orderId) }).start();
